// ../glass-ui.css (the AN.W1 SFC fold). Resolve ALL of them and gzip the
// concatenation — that is glass-ui's published /styles draw. A byte added to
// any cascade rung moves this number (the cascade arm is INSIDE the gate).
export function combinedStylesDraw(distRoot) {
    const stylesDir = resolve(distRoot, "styles");
    // Every relative `@import` is inlined, recursively and each sheet once: a CSS door
    // (`theme/index.css`) imports its partials, so the draw is the whole closure. A sheet an
    // import names that is not in dist fails the read.
    const seen = new Set();
    const inline = (file) => {
        if (seen.has(file)) return "";
        seen.add(file);
        return readFileSync(file, "utf-8").replace(/@import\s+["']([^"']+\.css)["'];?/g, (_m, ref) => `\n${inline(resolve(dirname(file), ref))}\n`);
    };
    const css = inline(resolve(stylesDir, "index.css"));
    return { raw: Buffer.byteLength(css), gzip: gzipSync(css).length };
}

